// Builds the generated files from the sources. Run from the repo root: node scripts/build.mjs  (no dependencies)
//   tokens/tokens.css         CSS variables (both themes, inverse bands, print), type classes
//   dist/storyville.css       fonts + tokens + components: what apps link or install
//   dist/tailwind-bridge.css  optional: Tailwind v4 utilities + shadcn variable mapping
//   manifest.json             version + sha256 of every file, for install/sync scripts
import { readFileSync, writeFileSync, mkdirSync, readdirSync, statSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { join } from 'node:path';

const version = readFileSync('VERSION', 'utf8').trim();
const t = JSON.parse(readFileSync('tokens/tokens.json', 'utf8'));
const [first, second] = t.color.themes.map((th) => th.id); // light (default), dark
const val = (v, theme) => {
  const raw = typeof v === 'string' ? v : (v[theme] ?? v[first]);
  return raw.replace(/^\{(.+)\}$/, 'var(--$1)');
};
const themed = t.color.tokens.filter((c) => typeof c.value === 'object');
const block = (theme, pad) => themed.map((c) => `${pad}--${c.name}: ${val(c.value, theme)};`);
const isLength = (fam) => !['name', 'version', 'meta', 'color', 'type'].includes(fam) && t[fam]?.tokens;

// ---------- tokens.css ----------
const o = [];
o.push(`/* Storyville RD ${version} — generated from tokens/tokens.json by scripts/build.mjs. Do not edit by hand. */`);
o.push('@layer svr {');
o.push(`  :root, [data-theme="${first}"] {`, `    color-scheme: ${first};`);
for (const c of t.color.tokens) o.push(`    --${c.name}: ${val(c.value, first)};`);
for (const fam of Object.keys(t).filter(isLength)) for (const x of t[fam].tokens) o.push(`    --${x.name}: ${x.value};`);
for (const [k, v] of Object.entries(t.type.families)) o.push(`    --svr-font-${k}: ${v};`);
o.push('  }');
o.push(`  [data-theme="${second}"] {`, `    color-scheme: ${second};`, ...block(second, '    '), '  }');
o.push('  /* No data-theme yet (before theme.js runs, or without JS): follow the device setting. */');
o.push(`  @media (prefers-color-scheme: ${second}) {`, `    :root:not([data-theme="${first}"]) {`, `      color-scheme: ${second};`, ...block(second, '      '), '    }', '  }');
o.push('  /* INVERSE-START: an inverse band takes the opposite theme. */');
o.push('  .svr-surface-inverse {', `    color-scheme: ${second};`, ...block(second, '    '), '  }');
// The :not() skips bands inside a light wrapper within a dark page (client content in a dark staff app): those stay charcoal.
o.push(`  [data-theme="${second}"] .svr-surface-inverse:not([data-theme="${second}"] [data-theme="${first}"] *) {`, `    color-scheme: ${first};`, ...block(first, '    '), '  }');
o.push(`  @media (prefers-color-scheme: ${second}) {`, `    :root:not([data-theme="${first}"]) .svr-surface-inverse:not([data-theme="${first}"] *) {`, `      color-scheme: ${first};`, ...block(first, '      '), '    }', '  }');
o.push('  /* Nav and sidebar surface: always the dark theme (charcoal), in both page themes. */');
o.push('  .svr-nav {', `    color-scheme: ${second};`, ...block(second, '    '), '  }');
o.push('  /* INVERSE-END */');
o.push('  /* Print is always light; inverse bands stay inverse. */');
o.push('  /* :not([data-svr-print]) only raises specificity so print beats the screen-theme rules above. */', '  @media print {', `    :root:not([data-svr-print]), [data-theme]:not([data-svr-print]) {`, `      color-scheme: ${first};`, ...block(first, '      '), '    }',
  '    :root:not([data-svr-print]) .svr-surface-inverse:not([data-svr-print] *), [data-theme]:not([data-svr-print]) .svr-surface-inverse:not([data-svr-print] *) {', `      color-scheme: ${second};`, ...block(second, '      '), '    }', '  }');
for (const g of t.type.groups) for (const s of g.styles) {
  const fam = s.family || g.family;
  o.push(`  .${s.name} { font-family: var(--svr-font-${fam}); font-size: ${s.fontSize}; line-height: ${s.lineHeight}; font-weight: ${s.fontWeight};${s.letterSpacing ? ` letter-spacing: ${s.letterSpacing};` : ''} }`);
}
o.push('}');
const tokensCss = o.join('\n') + '\n';
writeFileSync('tokens/tokens.css', tokensCss);

// ---------- dist/storyville.css ----------
const fonts = readFileSync('fonts/fonts.css', 'utf8').replaceAll("url('./", "url('../fonts/");
mkdirSync('dist', { recursive: true });
writeFileSync('dist/storyville.css', fonts + '\n' + tokensCss + '\n' + readFileSync('css/components.css', 'utf8'));

// ---------- dist/tailwind-bridge.css ----------
const b = [];
b.push(`/* Storyville RD ${version} — Tailwind v4 + shadcn/ui bridge. Generated by scripts/build.mjs. Do not edit by hand.`);
b.push('   Use in a Tailwind v4 app, after @import "tailwindcss" (and after storyville.css is loaded):');
b.push('     @import "./vendor/svr_brand/dist/tailwind-bridge.css";');
b.push('   Tailwind must process this file, so install (vendor) it; a CDN <link> will not work. See INSTALL.md. */');
b.push('');
b.push('/* Tailwind dark: variant follows the brand theme attribute (theme.js always sets it). */');
b.push('@custom-variant dark (&:where([data-theme="dark"], [data-theme="dark"] *));');
b.push('');
b.push('/* Brand tokens as utilities: bg-svr-bg, text-svr-text-muted, border-svr-border-strong, bg-svr-danger-subtle,');
b.push('   font-svr-display, rounded-svr-md, p-svr-4 … */');
b.push('@theme inline {');
for (const c of t.color.tokens) b.push(`  --color-${c.name.replace(/^svr-color-/, 'svr-')}: var(--${c.name});`);
for (const [k] of Object.entries(t.type.families)) b.push(`  --font-svr-${k}: var(--svr-font-${k});`);
for (const x of t.radius.tokens) b.push(`  --radius-${x.name.replace(/^svr-radius-/, 'svr-')}: var(--${x.name});`);
for (const x of t.spacing.tokens) b.push(`  --spacing-${x.name.replace(/^svr-space-/, 'svr-')}: var(--${x.name});`);
b.push('}');
b.push('');
b.push('/* shadcn/ui variables mapped to brand role tokens. These flip with the theme on their own,');
b.push('   so delete the app\'s own :root { --background … } and .dark { … } blocks. */');
const map = {
  background: 'bg', foreground: 'text', card: 'bg', 'card-foreground': 'text', popover: 'surface-alt', 'popover-foreground': 'text',
  primary: 'accent-fill', 'primary-foreground': 'on-accent', secondary: 'surface-alt', 'secondary-foreground': 'heading',
  muted: 'surface-alt', 'muted-foreground': 'text-muted', accent: 'surface-alt', 'accent-foreground': 'heading',
  destructive: 'danger', 'destructive-foreground': 'on-danger', border: 'border', input: 'border-strong', ring: 'focus',
  'chart-1': 'chart-1', 'chart-2': 'chart-2', 'chart-3': 'chart-3', 'chart-4': 'chart-4', 'chart-5': 'chart-5',
  sidebar: 'surface-alt', 'sidebar-foreground': 'text', 'sidebar-primary': 'accent-fill', 'sidebar-primary-foreground': 'on-accent',
  'sidebar-accent': 'bg', 'sidebar-accent-foreground': 'heading', 'sidebar-border': 'border', 'sidebar-ring': 'focus',
};
b.push('@layer svr {', '  :root {');
for (const [k, v] of Object.entries(map)) b.push(`    --${k}: var(--svr-color-${v});`);
b.push('    --radius: var(--svr-radius-md);', '  }', '}');
writeFileSync('dist/tailwind-bridge.css', b.join('\n') + '\n');

// ---------- manifest.json ----------
const SKIP = new Set(['.git', 'node_modules', 'manifest.json', '.DS_Store']);
const walk = (dir) => readdirSync(dir).flatMap((n) => {
  if (SKIP.has(n) || n.startsWith('.') || n.endsWith('.zip')) return []; // dotfiles (.git, .github, .gitignore) aren't part of a release
  const p = dir === '.' ? n : join(dir, n);
  return statSync(p).isDirectory() ? walk(p) : [p.split('\\').join('/')];
});
// Hash what a release contains: the LF text git stores, not a Windows CRLF working copy (the installer
// compares against the release as downloaded). Gitignored build output isn't in a release, so skip it.
import { execSync } from 'node:child_process';
let listed;
try { listed = execSync('git ls-files -co --exclude-standard', { encoding: 'utf8', maxBuffer: 1e8 }).split(/\r?\n/).filter(Boolean); } catch { listed = null; }
const inRelease = (p) => !p.split('/').some((n) => SKIP.has(n) || n.startsWith('.')) && !p.endsWith('.zip') && p !== 'manifest.json';
const paths = (listed ? listed.filter(inRelease) : walk('.')).sort();
const files = paths.map((path) => {
  let buf = readFileSync(path);
  if (!buf.includes(0)) buf = Buffer.from(buf.toString('latin1').replace(/\r\n/g, '\n'), 'latin1'); // text only
  return { path, bytes: buf.length, sha256: createHash('sha256').update(buf).digest('hex') };
});
writeFileSync('manifest.json', JSON.stringify({ name: 'svr_brand', version, files }, null, 2) + '\n');
console.log(`Built ${version}: tokens/tokens.css, dist/storyville.css, dist/tailwind-bridge.css, manifest.json (${files.length} files)`);
